{"code":"def transform(grid):
    a=[r[:] for r in grid]
    from collections import Counter
    cnt=Counter(x for row in grid for x in row)
    bg=cnt.most_common(1)[0][0]
    colors=[c for c in cnt if c!=bg]
    # object is the most frequent non-background color
    obj=max(colors,key=lambda c:cnt[c])
    pts=[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==obj]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    # all other colored cells are beacons; draw straight connectors
    for r,row in enumerate(grid):
        for c,x in enumerate(row):
            if x!=bg and x!=obj:
                if r0<=r<=r1:
                    if c<c0:
                        for j in range(c,c0): a[r][j]=x
                    elif c>c1:
                        for j in range(c1+1,c+1): a[r][j]=x
                elif c0<=c<=c1:
                    if r<r0:
                        for i in range(r,r0): a[i][c]=x
                    elif r>r1:
                        for i in range(r1+1,r+1): a[i][c]=x
    return a"}

